import { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { trackAppDownload } from './AppStoreBadges';
import iconUrl from '../public/monitor_icon_64.png';

/**
 * Thin App Store call to action that floats at the bottom of every article.
 * The whole bar is the link, so it's an easy tap target on a phone.
 */
export default function ArticleDownloadBar() {
  const { t } = useTranslation('edb');
  const [shown, setShown] = useState(false);

  // Slide in after first paint rather than rendering in place.
  useEffect(() => {
    const id = requestAnimationFrame(() => setShown(true));
    document.body.classList.add('has-download-bar');
    return () => {
      cancelAnimationFrame(id);
      document.body.classList.remove('has-download-bar');
    };
  }, []);

  return (
    <a
      href="https://apps.apple.com/us/app/external-display-browser/id6758286241"
      target="_blank"
      rel="noopener noreferrer"
      className={`article-download-bar${shown ? ' is-shown' : ''}`}
      data-fast-goal="ios_download"
      onClick={trackAppDownload}
    >
      <img className="article-download-bar-icon" src={iconUrl} alt="" width={36} height={36} decoding="async" />
      <span className="article-download-bar-text">{t('downloadBar.text')}</span>
      <img
        className="article-download-bar-badge"
        src="/app-store-badge.svg"
        alt={t('appStore.downloadButton')}
        width={126}
        height={42}
        decoding="async"
      />
    </a>
  );
}
